__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    const int TILE_SIZE = 32;
    const int THREAD_TILE_SIZE = 8;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Calculate starting positions for this thread's tile
    int row_start = by * TILE_SIZE + ty * THREAD_TILE_SIZE;
    int col_start = bx * TILE_SIZE + tx * THREAD_TILE_SIZE;

    // Register arrays for accumulation
    float sum[THREAD_TILE_SIZE][THREAD_TILE_SIZE];

    // Initialize accumulation registers
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_SIZE; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_SIZE; ++j) {
            sum[i][j] = 0.0f;
        }
    }

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles into shared memory
        #pragma unroll
        for (int i = 0; i < THREAD_TILE_SIZE; ++i) {
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_SIZE; ++j) {
                int A_row = by * TILE_SIZE + ty * THREAD_TILE_SIZE + i;
                int A_col = t * TILE_SIZE + tx * THREAD_TILE_SIZE + j;
                int B_row = t * TILE_SIZE + ty * THREAD_TILE_SIZE + i;
                int B_col = bx * TILE_SIZE + tx * THREAD_TILE_SIZE + j;

                if (ty * THREAD_TILE_SIZE + i < TILE_SIZE && tx * THREAD_TILE_SIZE + j < TILE_SIZE) {
                    As[ty * THREAD_TILE_SIZE + i][tx * THREAD_TILE_SIZE + j] = 
                        (A_row < N && A_col < N) ? A[A_row * N + A_col] : 0.0f;
                    Bs[ty * THREAD_TILE_SIZE + i][tx * THREAD_TILE_SIZE + j] = 
                        (B_row < N && B_col < N) ? B[B_row * N + B_col] : 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial products
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            #pragma unroll
            for (int i = 0; i < THREAD_TILE_SIZE; ++i) {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_SIZE; ++j) {
                    if (ty * THREAD_TILE_SIZE + i < TILE_SIZE && tx * THREAD_TILE_SIZE + j < TILE_SIZE) {
                        sum[i][j] += As[ty * THREAD_TILE_SIZE + i][k] * Bs[k][tx * THREAD_TILE_SIZE + j];
