                }
            }
        }

        __syncthreads();
    }

    // Write results
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_SIZE; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_SIZE; ++j) {
            int row = row_start + i;
            int col = col_start + j;
            if (row < N && col < N) {
                C[row * N + col] = sum[i][j];
            }
        }
    }
}

